    #[local] Abbreviation bc_facts := (@HEmplace2U1A.bc_facts AC L MI ST NEW_STACK DEL_STACK fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K U0 Hlast ROOM2 CONT).
