    #[local] Abbreviation foot_offimg_gen := (@HEmplace2U1A.foot_offimg_gen AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo A0 s R0 M0 model0 sp ret obj keyp2 CB ASP).
    #[local] Abbreviation foot_apart_new := (@HEmplace2U1A.foot_apart_new AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K CB U0 ASP CONT).
    #[local] Abbreviation pst := (@HEmplace2U1A.pst L NEW_STACK DEL_STACK R0 M0 sp ret obj bc tupp key).
    #[local] Abbreviation phaseA := (@HEmplace2U1A.phaseA AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn fx A0 s R0 M0 model0 sp ret obj bl bc keyp tupp keyp2 key ents K CB H10 H11 H13 U0 ASP ASK CK Hlast ROOM2 CONT).
    #[local] Abbreviation epilogue := (@HEmplace2U1A.epilogue AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K CB CONT).
