    #[local] Abbreviation phaseI := (@HEmplace2U1A.phaseI AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img fx A0 s R0 M0 model0 sp ret obj bl bc keyp tupp keyp2 key ents K CB FRM U0 ASP AST ASK2 CK K2AL HSZ Hlast ROOM2 CONT).
    #[local] Abbreviation finish := (@HEmplace2U1A.finish AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K CB U0 ASP CONT).
    #[local] Abbreviation lnk_chain := (@HEmplace2U1A.lnk_chain AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn A0 s R0 M0 model0 sp ret bc keyp2 ents CB ROOM2).
    #[local] Abbreviation lnk_app := (@HEmplace2U1A.lnk_app AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn A0 s R0 M0 model0 sp ret bc keyp2 ents CB ROOM2).
    #[local] Abbreviation lnk_agree := (@HEmplace2U1A.lnk_agree sp keyp2).
    #[local] Abbreviation umapx_link := (@HEmplace2U1A.umapx_link AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn A0 s R0 M0 model0 sp ret obj bc keyp keyp2 key ents CB ASP CK ROOM2).
    #[local] Abbreviation umap_foot_mono := (@HEmplace2U1A.umap_foot_mono obj).
    #[local] Abbreviation phaseF_pn := (@HEmplace2U1A.phaseF_pn AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc keyp keyp2 key ents K CB U0 ASP CK HSZ ROOM2 CONT).
    #[local] Abbreviation SPF := sp_facts.
    #[local] Notation ent := (Z * (Z * Z))%type.
    Ltac base_from HR' Bprev :=
      let Q2 := fresh in let Q3 := fresh in let Q4 := fresh in
      rreg HR' 2%bv Q2; rreg HR' 3%bv Q3; rreg HR' 4%bv Q4;
      let Bc := fresh in let B2 := fresh in let B3 := fresh in let B4 := fresh in let Bs := fresh in
      pose proof Bprev as Bc; destruct Bc as (B2 & B3 & B4 & Bs);
      unfold base_ok; rewrite Q2, Q3, Q4; split; [first [reflexivity | exact B2] |]; split; [exact B3|]; split; [exact B4|];
      let r := fresh "r" in let Hr := fresh "Hr" in
      intros r Hr; rewrite (syms_id_sound _ _ _ _ [21; 22; 23; 24; 25; 26; 27]%bv HR' eq_refl r Hr); apply Bs; exact Hr.

    Ltac nadd := repeat match goal with |- context [alu64 ALU_ADD (Z_to_bv 64 ?a) (Z_to_bv 64 ?k)] => first [rewrite (w_add a k) by lia | rewrite (w_addm a k) by lia] end.
    Ltac nrw Hj := nadd; repeat match goal with |- context [?x + -1] => change (x + -1) with (x - 1) end;
                   rewrite ?w_and, ?w_remu by lia; rewrite ?w_mul by lia; nadd; rewrite ?v_addi_Z by lia; rewrite ?Z.add_0_r; rewrite ?Hj.
    Ltac fin5 FIN HR' extra wit Hj :=
      eapply (FIN _ _ extra); [ wit | evs; nrw Hj; reflexivity
        | let Q := fresh in rreg HR' 2%bv Q; exact Q
        | let Q := fresh in rreg HR' 3%bv Q; exact Q
        | let Q := fresh in rreg HR' 4%bv Q; exact Q
        | exact (syms_id_sound _ _ _ _ [21; 22; 23; 24; 25; 26; 27]%bv HR' eq_refl)
        | let Q := fresh in rreg HR' 8%bv Q; exact Q
        | let Q := fresh in rreg HR' 10%bv Q; exact Q ].

    Ltac scE Hland Hj DEFp HDEF DEFbl :=
      split_scs;
      lazymatch goal with
      | |- sc_denot _ _ _ (SCStoreOk _ _) =>
          eapply sc_storeok; [evs; nrw Hj; reflexivity | lia | cbn [a_off]; lia | cbn [a_off]; lia
                            | cbn [a_off]; rewrite ?Z.add_0_r;
                              first [ lazymatch goal with |- defined _ ?a _ => match goal with D : defined _ a _ |- _ => eapply (defined_sub _ _ _ _ _ D); lia end end
                                    | eapply (defined_sub _ _ _ _ _ HDEF); lia | eapply (defined_sub _ _ _ _ _ DEFp); lia | eapply (defined_sub _ _ _ _ _ DEFbl); lia] ]
      | |- sc_denot _ _ _ (SCFlat _ _) => eapply sc_flat; [evs; nrw Hj; reflexivity | lia | cbn [a_off]; lia | lia | cbn [a_off]; lia]

      | |- sc_denot _ _ _ (SCBr false BC_NE (EAlu ALU_AND _ (ELit 7)) (ELit 0)) =>
          eapply sc_trap_align; [evs; nrw Hj; reflexivity | lia
                                | first [assumption | apply align16_8; assumption | apply align8_add; apply align16_8; assumption
                                        | rewrite Z.add_comm; apply align8_add; apply align16_8; assumption] ]
      | |- sc_denot _ _ _ (SCBr false BC_NE (EAlu ALU_SRL _ (ELit 61)) (ELit 0)) => eapply sc_trap_srl; [evs; nrw Hj; reflexivity | lia | lia]
      | |- sc_denot _ _ _ (SCBr false BC_LTU (EAlu ALU_ADD (EMd M_MUL (ELit (-1)) _) (ELit (-1))) _) =>
          eapply sc_trap_notlt; [evs; rewrite w_notexpr by lia; reflexivity | evs; nrw Hj; reflexivity | lia | lia | lia]
      | |- sc_denot _ _ _ (SCBr false BC_EQ (EAlu ALU_SLTU (ELit 0) _) (EAlu ALU_SLTU _ (ELit 1))) =>
          eapply (sc_trap_nulleq _ _ _ _ _ (8 * _)); [evs; reflexivity | evs; nrw Hj; first [reflexivity | rewrite Z.add_comm; reflexivity] | lia | lia | lia]
      | |- sc_denot _ _ _ (SCBr false BC_LTU (EAlu ALU_ADD (EMd M_MUL (ELit 8) _) _) _) =>
          eapply (sc_trap_wrap _ _ _ _ _ _ (8 * _)); [evs; nrw Hj; first [reflexivity | rewrite Z.add_comm; reflexivity] | evs; reflexivity | lia | lia | lia]
      | |- sc_denot _ _ _ (SCBr _ _ _ _) => cbn [sc_denot]; evs; nrw Hj; rewrite ?Hland; rewrite ?br_ne, ?br_eq, ?br_ltu, ?br_geu, ?br_eq_sxw, ?br_ne_sxw by lia; bool_lia
      | |- sc_denot _ _ _ (SCReadBase _ _ _ _) =>
          first [ match goal with H : cellw _ _ _ _ _ |- _ =>
                    eapply (sc_read_cellw _ _ _ _ _ _ _ _ H); [first [apply N.le_refl | cbn; lia] | evs; nrw Hj; first [reflexivity | f_equal; lia] | evs; reflexivity] end
                | sc_auto1 ]
      | |- _ => sc_auto1
      end.

    #[local] Abbreviation phaseF_empty := (HEmplace2U1B.phaseF_empty (AC:=AC) L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc keyp keyp2 key ents K CB U0 ASP CK ROOM2 CONT).

    Lemma phaseINS : forall (fx1 : FPState) p A M model R (bl2 bc2 : Z) (ents2 : list ent) (rh : bool) (F : Z -> Prop),
      core p A M model R -> frm_zero (@fp_csr fx1) -> fkept_u1 fx fx1 -> bc2 <> 0 -> Zlength ents + 1 <= bc2 ->
      getr R 18%bv = Z_to_bv 64 bc2 -> getr R 20%bv = Z_to_bv 64 (hmod key bc2) ->
      umapx MI 24 (nval24 SEGS) A M obj bl2 bc2 ents2 -> Permutation ents2 ents ->
      (forall q m, In (q, m) (umap_blocks 24 bl2 bc2 ents2) -> apart p 24 q m) ->
      (rh = false -> bl2 = bl /\ bc2 = bc) -> (rh = true -> (bc = 0 \/ Zlength ents = bc) /\ bc2 = bseq_next bc) ->
      lapply (live MI A0) (LAdd p 24 :: (if rh then LAdd bl2 (8 * bc2) :: (if bc =? 0 then [] else [LDel bl]) else [])) (live MI A) ->
      eff MI A0 A M0 M W F -> (forall a, F a -> p <= a < p + 24 \/ umap_foot 24 obj bl bc ents a \/ umap_foot 24 obj bl2 bc2 ents2 a) ->
      (forall a, F a -> ~ in_ranges (ly_img L) a) ->
      srealizes SEGS (cfg fx1 R INS M model) K.
Proof using AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc keyp keyp2 key ents K CB U0 ASP CK HSZ ROOM2 CONT.
Ltac finI HR' CO Hdummy :=
        first [ let Q := fresh in rreg HR' 18%bv Q; exact Q
              | let Q := fresh in rreg HR' 14%bv Q; exact Q
              | let Q := fresh in rreg HR' 11%bv Q; exact Q
              | let Q := fresh in rreg HR' 13%bv Q; rewrite Q; nrw Hdummy; first [reflexivity | f_equal; lia]
