      rc_pnew : ~ In p (map fst (live MI A0));
      rc_n0 : cell8 SEGS M p 0;
      rc_nh : cell8 SEGS M (p + 8) key;
      rc_nk : cell4 SEGS M (p + 16) key;
      rc_nv : cell4 SEGS M (p + 20) 0;
      rc_pdef : defined M p 24;
      rc_eff : eff MI A0 A M0 M W (fun a => p <= a < p + 24);
      rc_ladd : live_add p 24 (live MI A0) (live MI A);
      rc_U : umapx MI 24 (nval24 SEGS) A M obj bl bc ents;
      rc_grow : bc = 0 \/ Zlength ents = bc;
      rc_roc : ro_clear L M
    }.

    Lemma phaseR1 : forall (fx1 : FPState) p A M model R,
      core p A M model R -> getr R 18%bv = Z_to_bv 64 bc ->
      frm_zero (@fp_csr fx1) -> fkept_u1 fx fx1 -> fholds fx1 14%bv (ieee (Zlength ents + 1)) -> fholds fx1 15%bv one32 ->
      (bc = 0 \/ Zlength ents = bc) ->
      eff MI A0 A M0 M W (fun a => p <= a < p + 24) -> live_add p 24 (live MI A0) (live MI A) ->
      umapx MI 24 (nval24 SEGS) A M obj bl bc ents -> ro_clear L M ->
      (forall (fx2 : FPState) R', frm_zero (@fp_csr fx2) -> fkept_u1 fx fx2 -> rcall p A M model R' -> srealizes SEGS (cfg fx2 R' RW M model) K) ->
      srealizes SEGS (cfg fx1 R GROW M model) K.
Proof using AC L MI ST NEW_STACK DEL_STACK fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K U0 HSZ Hlast ROOM2 CONT.
