    Lemma phaseR2 : forall (fx2 : FPState) p A M model R,
      frm_zero (@fp_csr fx2) -> fkept_u1 fx fx2 -> rcall p A M model R -> srealizes SEGS (cfg fx2 R RW M model) K.
Proof using AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn RWH HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc keyp keyp2 key ents K CB U0 ASP CK HSZ HNMAX Hlast ROOM2 CONT.
Ltac finR FINR HR' Hj :=
          eapply FINR;
          [ let Q := fresh in rreg HR' 2%bv Q; exact Q
          | let Q := fresh in rreg HR' 3%bv Q; exact Q
          | let Q := fresh in rreg HR' 4%bv Q; exact Q
          | exact (syms_id_sound _ _ _ _ [21; 22; 23; 24; 25; 26; 27]%bv HR' eq_refl)
          | let Q := fresh in rreg HR' 8%bv Q; exact Q
          | let Q := fresh in rreg HR' 19%bv Q; exact Q
          | let Q := fresh in rreg HR' 10%bv Q; exact Q
          | let Q := fresh in rreg HR' 18%bv Q; exact Q
          | let Q := fresh in rreg HR' 20%bv Q; rewrite Q; nrw Hj; first [reflexivity | f_equal; lia] ].
Ltac scR Hland Hj Hd := scE Hland Hj Hd Hd Hd.
